import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#define BM 128
#define BN 128
#define BK 16
#define TM 8
#define TN 8
// ---- cp.async helpers (sm_80+) ----
// Copies 16 bytes global->shared; src_bytes < 16 zero-fills the remainder.
__device__ __forceinline__ void cp_async16(void* smem_dst, const void* gmem_src, int src_bytes) {
    unsigned dst = (unsigned)__cvta_generic_to_shared(smem_dst);
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16, %2;\n"
                 :: "r"(dst), "l"(gmem_src), "r"(src_bytes));
}
__device__ __forceinline__ void cp_async_commit() {
    asm volatile("cp.async.commit_group;\n" ::);
}
__device__ __forceinline__ void cp_async_wait1() {
    asm volatile("cp.async.wait_group 1;\n" ::);
}
__device__ __forceinline__ void cp_async_wait0() {
    asm volatile("cp.async.wait_group 0;\n" ::);
}
// Tiled shared-memory SGEMM: C(MxN) = A(MxK) * B(KxN)
// Each block computes a 128x128 tile of C; each of the 256 threads computes an 8x8 sub-tile.
// Optimization: cp.async double-buffered pipeline. Global->shared copies are issued
// asynchronously (bypassing register staging), so no aFrag/bFrag register arrays are
// needed and the memory latency of the next K-tile overlaps the FMA work directly.
__global__ void matmul_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int N, int K,
                              bool vec_ok) {
    __shared__ __align__(16) float As[2][BM][BK];  // row-major A tile (m, k)
    __shared__ __align__(16) float Bs[2][BK][BN];  // row-major B tile (k, n)
    const int tid = threadIdx.x;
    const int bm = blockIdx.y * BM;
    const int bn = blockIdx.x * BN;
    // compute-tile coordinates of this thread
    const int tx = tid % (BN / TN);  // 0..15
    const int ty = tid / (BN / TN);  // 0..15
    // loader indices for the A tile (BM x BK), 16B copies: 4 threads/row, 64 rows/pass
    const int aRow = tid / (BK / 4);
    const int aCol = (tid % (BK / 4)) * 4;
    // loader indices for the B tile (BK x BN), 16B copies: 32 threads/row, 8 rows/pass
    const int bRow = tid / (BN / 4);
    const int bCol = (tid % (BN / 4)) * 4;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            acc[i][j] = 0.0f;
    // ---- Compute on the resident tile in buffer `buf` ----
    auto computeTile = [&](int buf) {
        #pragma unroll
        for (int k = 0; k < BK; ++k) {
            float rA[TM];
            float rB[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                rA[i] = As[buf][ty * TM + i][k];
            #pragma unroll
            for (int j = 0; j < TN; j += 4)
                *reinterpret_cast<float4*>(&rB[j]) =
                    *reinterpret_cast<const float4*>(&Bs[buf][k][tx * TN + j]);
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    acc[i][j] += rA[i] * rB[j];
        }
    };
    if (vec_ok) {
        // ---- cp.async double-buffered pipeline ----
        // vec_ok guarantees K%4==0 and N%4==0, so every in-bounds 16B copy is aligned
        // and fully inside the matrix row (gCol%4==0 && gCol<K => gCol+3<K).
        auto loadTileAsync = [&](int k0, int buf) {
            #pragma unroll
            for (int r = 0; r < BM; r += 64) {
                int gRow = bm + aRow + r;
                int gCol = k0 + aCol;
                const float* src = A;
                int bytes = 0;
                if (gRow < M && gCol < K) {
                    src = A + (long)gRow * K + gCol;
                    bytes = 16;
                }
                cp_async16(&As[buf][aRow + r][aCol], src, bytes);
            }
            #pragma unroll
            for (int r = 0; r < BK; r += 8) {
                int gRow = k0 + bRow + r;
                int gCol = bn + bCol;
                const float* src = B;
                int bytes = 0;
                if (gRow < K && gCol < N) {
                    src = B + (long)gRow * N + gCol;
                    bytes = 16;
                }
                cp_async16(&Bs[buf][bRow + r][bCol], src, bytes);
            }
            cp_async_commit();
        };
        // ---- Prologue: fill buffer 0 ----
        loadTileAsync(0, 0);
        int cur = 0;
        for (int k0 = 0; k0 < K; k0 += BK) {
            const int knext = k0 + BK;
            // Issue async global->shared copies for the next tile BEFORE computing
            // on the current one, so the memory latency hides behind the FMA work.
            // (The trailing __syncthreads of the previous iteration guarantees no
            // thread is still reading the buffer being overwritten.)
            if (knext < K) {
                loadTileAsync(knext, cur ^ 1);
                cp_async_wait1();  // current tile arrived; next tile still in flight
            } else {
                cp_async_wait0();  // last tile: drain all outstanding groups
            }
            __syncthreads();
            computeTile(cur);
            __syncthreads();
            cur ^= 1;
        }
    } else {
        // ---- Generic fallback (unaligned K/N): scalar loads, same double buffering ----
        auto loadTile = [&](int k0, int buf) {
            #pragma unroll
            for (int r = 0; r < BM; r += 64) {
                int gRow = bm + aRow + r;
                #pragma unroll
                for (int c = 0; c < 4; ++c) {
                    int gCol = k0 + aCol + c;
                    As[buf][aRow + r][aCol + c] =
                        (gRow < M && gCol < K) ? A[(long)gRow * K + gCol] : 0.f;
                }
            }
            #pragma unroll
            for (int r = 0; r < BK; r += 8) {
                int gRow = k0 + bRow + r;
                #pragma unroll
                for (int c = 0; c < 4; ++c) {
                    int gCol = bn + bCol + c;
                    Bs[buf][bRow + r][bCol + c] =
                        (gRow < K && gCol < N) ? B[(long)gRow * N + gCol] : 0.f;
                }
            }
        };
        loadTile(0, 0);
        __syncthreads();
        int cur = 0;
        for (int k0 = 0; k0 < K; k0 += BK) {
            const int knext = k0 + BK;
            if (knext < K) loadTile(knext, cur ^ 1);
            computeTile(cur);
            if (knext < K) {
                __syncthreads();
                cur ^= 1;
            }
        }
    }
    // ---- Write results ----
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int gRow = bm + ty * TM + i;
        if (gRow >= M) break;
        int gCol = bn + tx * TN;
        float* ptr = C + (long)gRow * N + gCol;
        if (vec_ok && gCol + TN <= N) {
            #pragma unroll
            for (int j = 0; j < TN; j += 4)
                *reinterpret_cast<float4*>(ptr + j) =
                    *reinterpret_cast<const float4*>(&acc[i][j]);
        } else {
            #pragma unroll
            for (int j = 0; j < TN; ++j)
                if (gCol + j < N) ptr[j] = acc[i][j];
        }
    }
}
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
                B.scalar_type() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");
    auto Ac = A.contiguous();
    auto Bc = B.contiguous();
    const int M = (int)Ac.size(0);
    const int K = (int)Ac.size(1);
    const int N = (int)Bc.size(1);
    auto C = torch::empty({M, N}, Ac.options());
    bool vec_ok = (K % 4 == 0) && (N % 4 == 0);
    dim3 block(256);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
